"""Returns the list of class labels from the given labels map.

    The class labels are returned for indexes sequentially from
    `min(1, min(labels_map))` to `max(labels_map)`. Any missing indices are
    given the label "class <index>".

    Args:
        a dictionary mapping indexes to label strings

    Returns:
        a list of class labels
    """
def get_class_labels(labels_map: Any) -> object {
    mini = min(1, min(labels_map));
    maxi = max(labels_map);
    return [labels_map.get(i, ("class %d" % i)) for i in range(mini, (maxi + 1))];
}

"""Remove any number in a string

    Args:
        s (str): A string that need to remove number

    Returns:
        A formatted string with no number
    """
def remove_numbers(s: Any) -> object {
    return ''.join(
        [
            i
            for i in s
            if not i.isdigit()
        ]
    );
}

"""
    :param item: tuple of ZSet (key, score)
    :param with_weight: keep decimal weighting of score, or return as int
    :param include_key: whether to include to raw key
    :return: dict of scoreboard item
    """
def decode_scoreboard_item(
    item: Any, with_weight: Any = False, include_key: Any = False
) -> object {
    key = item[0].decode('utf-8');
    data = key.split(">");
    score = item[1];
    if not with_weight {
        score = int(score);
    }
    output = {'name': data[0], 'affiliation': data[1], 'tid': data[2], 'score': score};
    if include_key {
        output['key'] = key;
    }
    return output;
}

"""Determine the target for the current CopyPhrase sequence.

    >>> copy_phrase_target("HELLO_WORLD", "")
    'H'
    >>> copy_phrase_target("HELLO_WORLD", "HE")
    'L'
    >>> copy_phrase_target("HELLO_WORLD", "HELLO_WORL")
    'D'
    >>> copy_phrase_target("HELLO_WORLD", "HEA")
    '<'
    >>> copy_phrase_target("HELLO_WORLD", "HEAL")
    '<'
    """
def copy_phrase_target(phrase: str, current_text: str, backspace: Any = '<') -> object {
    try {
        phrase.index(current_text);
        return phrase[len(current_text)];
    } except ValueError {
        return backspace;
    }
}

"""Create an underline string of a certain length

    :param level: The underline level specifying the symbol to use
    :param length: The string length
    :return: Underline string
    """
def set_underline(level: int, length: int) -> str {
    underline_symbol = ["`", "#", "*", "-", "^", '"', "="];
    symbol_str = underline_symbol[level] * length;
    return f"\n{symbol_str}\n";
}

"""Esconder as Configuracoes Painel de Controle, Impressoras e Conexoes de
    Rede

    DESCRIPTION
        Esta restricao remove as configuracoes Painel de Controle, Impressoras
    e Conexoes de Rede do menu Iniciar. Se as configuracoes da Barra de Tarefas
    tambem estiverem escondidas, acarretara na completa remocao das
    configuracoes.

    COMPATIBILITY
        Todos.

    MODIFIED VALUES
        NoSetFolders : dword : 00000000 = Desabilita restricao;
    00000001 = Habilita restricao.

    OBSERVATION
        Esta restricao deve desabilitar tambem a hotkey do Windows Explorer
    (SUPER + E).

    """
def no_set_folders(on: Any = 0) -> object {
    if on {
        return '''[HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\\
CurrentVersion\\Policies\\Explorer]
"NoSetFolders"=dword:00000001''';
    } else {
        return '''[HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\\
CurrentVersion\\Policies\\Explorer]
"NoSetFolders"=dword:00000000''';
    }
}
